-- 030: prevent direct public-schema reads of the agricultural corpus; expose only the authenticated search RPC
create or replace function private.search_agri_knowledge(query_text text,locality_filter text default null,crop_filter text default null,result_limit integer default 5) returns table(chunk_id uuid,source_id uuid,title text,publisher text,source_url text,published_on date,heading text,content text,locality_tags text[],crop_tags text[],rank real) language sql stable security definer set search_path='' as $$ select c.id,s.id,s.title,s.publisher,s.source_url,s.published_on,c.heading,c.content,c.locality_tags,c.crop_tags,ts_rank_cd(c.search_document,websearch_to_tsquery('simple',coalesce(query_text,'')))::real from public.agri_knowledge_chunks c join public.agri_knowledge_sources s on s.id=c.source_id where auth.uid() is not null and s.status='approved' and char_length(trim(coalesce(query_text,'')))>=2 and c.search_document @@ websearch_to_tsquery('simple',query_text) and (locality_filter is null or c.locality_tags && array[locality_filter,'Vhembe','Limpopo']::text[] or s.locality_tags && array[locality_filter,'Vhembe','Limpopo']::text[]) and (crop_filter is null or c.crop_tags && array[crop_filter]::text[] or s.crop_tags && array[crop_filter]::text[]) order by ts_rank_cd(c.search_document,websearch_to_tsquery('simple',coalesce(query_text,''))) desc,s.published_on desc nulls last limit greatest(1,least(coalesce(result_limit,5),8)); $$;
revoke all on function private.search_agri_knowledge(text,text,text,integer) from public,anon,authenticated;
grant usage on schema private to authenticated;
grant execute on function private.search_agri_knowledge(text,text,text,integer) to authenticated;
create or replace function public.search_agri_knowledge(query_text text,locality_filter text default null,crop_filter text default null,result_limit integer default 5) returns table(chunk_id uuid,source_id uuid,title text,publisher text,source_url text,published_on date,heading text,content text,locality_tags text[],crop_tags text[],rank real) language sql stable security invoker set search_path='' as $$ select * from private.search_agri_knowledge(query_text,locality_filter,crop_filter,result_limit); $$;
revoke all on function public.search_agri_knowledge(text,text,text,integer) from public,anon;
grant execute on function public.search_agri_knowledge(text,text,text,integer) to authenticated;
revoke select on public.agri_knowledge_sources,public.agri_knowledge_chunks from authenticated;